"use strict";(globalThis.webpackChunkgrc||=[]).push([[2973],{33238(e){e.exports=JSON.parse('{"citeKey":"yin2014rethinkingkey","slug":"yin-2014-rethinking-key-484a","title":"Rethinking Key-Value Store for Parallel I/O Optimization","authors":["Y. Yin","A. Kougkas","K. Feng","H. Eslami","Y. Lu","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"Data Intensive Scalable Computing Systems Workshop (DISCS), in conjunction with ACM/IEEE SuperComputing 2014, New Orleans, LA, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2014","year":2014,"era":"iit","month":11,"doi":"10.1109/discs.2014.11","abstract":"Key-Value Stores (KVStore) are being widely used as the storage system for large-scale Internet services and cloud storage systems. However, they are rarely used in HPC systems, where parallel file systems (PFS) are the dominant storage systems. In this study, we carefully examine the architecture difference and performance characteristics of PFS and KVStore. We propose that it is valuable to utilize KVStore to optimize the overall I/O performance, especially for the workloads that PFS cannot handle well, such as the cases with hurtful data synchronization or heavy metadata operations. To verify this proposal, we conducted comprehensive experiments with several synthetic benchmarks, an I/O benchmark, and a real application. The results show that our proposal is promising.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2014/yin-2014-rethinking-key-484a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["kougkas-anthony","feng-kun","sun-xian-he"]}')}}]);